local a={}function a.assign(b,c,d,e)if c=="thruster"then b.thrusters[d]=e elseif c=="sensor"then b.sensors[d]=e elseif c=="relay"then b.fuelRelay=e end;return b end;function a.candidates(f)local g={thruster={},sensor={},relay={}}for h,i in ipairs(f)do if i.type=="thruster"then g.thruster[#g.thruster+1]=i.name elseif i.type=="redstone_relay"then g.relay[#g.relay+1]=i.name elseif i.type=="monitor"then else g.sensor[#g.sensor+1]=i.name end end;return g end;local j=require("fcs.io.cfgspec")local k=require("fcs.io.fsx")local l="/eh2_hw_config.tbl"local m=k.read;local n=k.writeAtomic;local function o(read)local b,p=j.load("devbind",read)if not p then local q=read(l)if q~=nil then local r=textutils.unserialise(q)if type(r)=="table"then b=j.merge("devbind",j.splitLegacy(r).devbind)end end end;return b end;local function s(t)local g={}for h,e in ipairs(t.getNames())do g[#g+1]={name=e,type=t.getType(e)}end;return g end;local function u(v,w,x)print(("%s (current: %s)"):format(v,tostring(w)))if#x==0 then print("  (no candidates detected)")else for y,z in ipairs(x)do print(("  %d) %s"):format(y,z))end end;write("  pick #, type a name, or Enter to keep current: ")local A=read()if A==nil or A==""then return w end;local B=tonumber(A)if B and x[B]then return x[B]end;return A end;function a.run()local t=require("fcs.io.shim")local b=o(m)local C=j.defaults("devbind")local D=a.candidates(s(t))print("== EH2 BIND DEVICES ==")print("-- thrusters --")for d in pairs(C.thrusters)do b.thrusters[d]=u("thruster "..d,b.thrusters[d],D.thruster)end;print("-- sensors --")for d in pairs(C.sensors)do b.sensors[d]=u("sensor "..d,b.sensors[d],D.sensor)end;print("-- relay --")b.fuelRelay=u("fuel relay",b.fuelRelay,D.relay)j.save("devbind",b,n)print("written to "..j.FILES.devbind)end;return a